}

/**
 * موتور جستجو و جستجوی معنایی با دقت بالا
 */
صادرات جملات جستجوی تابع ناهمگام (
  query:string,
  فیلترها: SearchFilterOptions = {}
): Promise<{ نتایج: SentenceItem[]; total:number; semanticMatches؟: SemanticExplanationMatch[] }> {
  const all = await loadSentences();
  const normalizedQuery = normalizeText(query);
  const queryTokens = normalizedQuery ? normalizedQuery.split(' ').filter(Boolean) : [];

  const {
    cefr = 'همه'،
    بخش = 'همه'،
    دسته = 'همه'،
    زیر شاخه = 'همه'،
    گرامر = "همه"،
    رسمی = "همه"،
    حد = 50،
    افست = 0،
  } = فیلترها;

  // عبور فیلتر
  let filtered = all.filter(s => {
    if (cefr !== 'all' && s.cefr !== cefr) false;
    اگر (بخش !== 'همه' && s.section !==بخش) false;
    if (رده !== 'همه' && s.category !== دسته) false;
    اگر (زیررده !== 'همه' && s.subcategory !== زیررده) false;
    if (grammar !== 'all' && !s.grammar.toLowerCase().includes(grammar.toLowerCase())) false;
    if (formality !== 'all' && s.formality.toLowerCase() !== formality.toLowerCase()) false;
    بازگشت درست؛
  })؛

  if (!normalizedQuery) {
    const total = filtered.length;
    const paginated = فیلتر شده. برش (افست، افست + حد)؛
    بازگشت { نتایج: صفحه بندی شده، کل };
  }

  // الگوریتم امتیازدهی
  interfaceScoredItem {
    آیتم:SentenceItem;
    امتیاز: عدد;
    جنبه: SemanticExplanationMatch['matchedAspect'];
  }

  نتیجه امتیازدهی شده: ScoredItem[] = [];

  برای (consts of filtered) {
    اجازه دهید امتیاز = 0;
    let matchedAspect: SemanticExplanationMatch['matchedAspect'] = 'انگلیسی';

    const normEn = normalizeText(s.english);
    const normEg = normalizeText(s.arabicEg);
    const normFusha = normalizeText(s.arabicFusha);
    const normGrammar = normalizeText(s.grammar);
    const normPurpose = normalizeText(s.purpose);

    // مطابقت کامل جمله
    if (normEn === normalizedQuery) {
      امتیاز += 100;
      matchedAspect = 'انگلیسی';
    } else if (normEg === normalizedQuery) {
      امتیاز += 95;
      matchedAspect = 'عربی-مثال';
    } else if (normFusha === normalizedQuery) {
      امتیاز += 90;
      matchedAspect = 'عربی-فوشا';
    }

    //زیر رشته شامل
    if (normEn.includes(normalizedQuery)) {
      امتیاز += 50;
      matchedAspect = 'انگلیسی';
    } else if (normEg.includes(normalizedQuery)) {
      امتیاز += 45;
      matchedAspect = 'عربی-مثال';
    } else if (normFusha.includes(normalizedQuery)) {
      امتیاز += 40;
      matchedAspect = 'عربی-فوشا';
    } else if (normGrammar.includes(normalizedQuery)) {
      امتیاز += 35;
      matchedAspect = 'گرامر';
    } else if (normPurpose.includes(normalizedQuery)) {
      امتیاز += 30;
      matchedAspect = 'مفهوم';
    }

    // تطبیق نشانه
    اجازه دهید tokenMatches = 0;
    برای (توکن const queryTokens) {
      if (normEn.includes(token)) tokenMatches += 5;
      if (normEg.includes(token)) tokenMatches += 4;
      if (normFusha.includes(token)) tokenMatches += 3;
      if (s.vocabulary.some(v => normalizeText(v).includes(token))) tokenMatches += 4;
      if (s.tags.some(t => normalizeText(t).includes(token))) tokenMatches += 3;
    }
    امتیاز += tokenMatches;

    اگر (امتیاز > 0) {
      scored.push({ آیتم: s، امتیاز، جنبه: matchedAspect });
    }
  }

  scored.sort((a, b) => b.score - a.score);

  // توضیح معنایی برای موارد برتر مطابقت دارد
  const semanticMatches: SemanticExplanationMatch[] = scored.slice(0, 5).map(s => {
    اجازه دهید nuance = '';
    if (s.item.grammar.toLowerCase().includes('گذشته استمراری')) {
      nuance = 'زمان گذشته استمراری نشان می دهد که یک رویداد در زمان خاصی در گذشته در جریان بوده است.';
    } else if (s.item.grammar.toLowerCase().includes('present perfect continu')) {
      nuance = 'زمان حال کامل استمراری بر زمان گذشته تاکید می کند و تا لحظه صحبت ادامه می یابد.';
    } else if (s.item.grammar.toLowerCase().includes('future perfect')) {
      nuance = 'زمان کامل آینده بیانگر این است که یک رویداد قبل از زمان خاصی در آینده تکمیل خواهد شد.';
    } else if (s.item.grammar.toLowerCase().includes('indirect')) {
      nuance = 'شکل درخواست غیر مستقیم اوج آداب دیپلماتیک در ارتباطات انگلیسی است.';
    }
    بازگشت {
      جمله: s.item,
      مشابهت امتیاز: Math.min (100، s.score)،
      nuanceExplanationAr: nuance,
      matchedAspect: s.aspect,
    };
  })؛

  const total = امتیاز داده شد. طول؛
  const paginated = scored.slice(offset, offset + limit).map(s => s.item);

  بازگشت {
    نتایج: صفحه بندی شده،
    کل،
    مطابقت معنایی،
  };
}

/**
 * جمله روزانه قطعی (یکسان برای همه کاربران در هر روز مشخص)
 */
صادرات تابع async getDailySentence(): Promise<SentenceItem | null> {
  const all = await loadSentences();
  اگر (همه طول === 0) بازگشت null;

  const today = new Date();
  const dayOfYear = Math.floor(
    (today.getTime() - تاریخ جدید (today.getFullYear()، 0, 0).getTime()) / 1000 / 60 / 60 / 24
  )
  const index = Math.abs((dayOfYear * 97 + today.getFullYear()) % all.length);
  برگرداندن همه[index] || همه[0];
}

/**
 * جمله قطعی هفته
 */
صادرات تابع async getSentenceOfTheWeek(): Promise<SentenceItem | null> {
  const all = await loadSentences();
  اگر (همه طول === 0) بازگشت null;

  const today = new Date();
  const weekNumber = Math.ceil(
    ((today.getTime() - تاریخ جدید(today.getFullYear()، 0, 1). getTime()) / 86400000 + 1) / 7
  )
  // B2 یا C1 را برای جمله هفته ترجیح دهید
  const b2c1 = all.filter(s => s.cefr === 'B2' || s.cefr === 'C1');
  const pool = b2c1.length > 0 ? b2c1:all;
  Const index = Math.abs((weekNumber * 31) % pool.length);
  استخر بازگشتی[index] || استخر[0];
}

/**
 * جمله تصادفی، CEFR اختیاری یا فیلتر بخش را دریافت کنید
 */
صادرات تابع ناهمگام getRandomSentence(cefr?: CEFRLLevel, section?: string): Promise<SentenceItem | null> {
  const all = await loadSentences();
  let pool = همه;
  اگر (cefr) {
    pool = pool.filter(s => s.cefr === cefr);
  }
  اگر (بخش) {
    استخر = استخر. filter(s => s. section === section);
  }
  if (pool. length === 0) return null;
  const randIdx = Math.floor(Math.random() * pool.length);
  استخر بازگشتی[randIdx];
}
